(x, y, t) => {
  const w1x = Math.sin(x*0.008+t*0.15)*Math.cos(y*0.012-t*0.1)*40;
  const w1y = Math.cos(x*0.01-t*0.12)*Math.sin(y*0.009+t*0.13)*40;
  const x1 = x+w1x, y1 = y+w1y;
  const w2x = Math.sin(x1*0.015+t*0.2)*Math.cos(y1*0.018-t*0.15)*20;
  const w2y = Math.cos(x1*0.017-t*0.18)*Math.sin(y1*0.013+t*0.22)*20;
  const sx = x1+w2x, sy = y1+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+1)*40,0.05,2.4]
  ];
  let aS=0,bS=0,cS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    bS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    cS+=Math.cos(d*f*0.5-t*sp*0.8+3.0);
  }
  const act=aS/8,inh=bS/8,cat=cS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3+Math.sin(sx*0.07+t*0.5)*Math.cos(sy*0.06-t*0.7)*0.4;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8))*0.3;
  const reaction=Math.tanh((act-inh*0.6+cat*0.4+bg*0.25+spiral)*2.2);
  const diffusion=Math.tanh((inh*0.8-cat*0.5+act*0.3+spiral*0.5)*1.8);
  const combined=reaction*0.7+diffusion*0.3;
  const cellVal=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(dist*0.08-ang*5+t)*0.3;
  const cell=Math.tanh(cellVal*1.5)*0.25;
  const blend=combined*0.7+cell*0.3,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,85,120],[25,135,130],[80,170,110],[170,195,75],[220,190,55],[215,140,60],[195,95,65],[160,55,70],[100,30,65],[50,18,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(combined*Math.PI)*0.15;
  const edge=Math.abs(combined)>0.65?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(combined)*0.5)*0.1;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*120)|0)
  ];
}
